import type { PropsWithChildren } from 'react';
import { isElement } from 'react-is';

import type { DataTestId } from '../../core/types/data-props.js';
import type { StylingProps } from '../../core/types/styling-props.js';

/**
 * Typeguard function that will check if a React.Node is a SelectV2.Group
 * @internal
 */
export function _isSelectV2GroupLabelElement(
  element: React.ReactNode,
): element is React.ReactElement<SelectV2GroupLabelProps> {
  if (isElement(element) && element.type === SelectV2GroupLabel) {
    return true;
  }
  return false;
}

/**
 * Props for the SelectV2GroupLabel component.
 */
export type SelectV2GroupLabelProps = PropsWithChildren<unknown> &
  StylingProps &
  DataTestId;

/**
 * `SelectV2.GroupLabel` defines the label of an option group. The component
 * is only valid within a `SelectV2.Group`.
 *
 * @example
 * ```tsx
 * <SelectV2.Group>
 *   <SelectV2.GroupLabel>Colors</SelectV2.GroupLabel>
 *   <SelectV2.Option value="red">Red</SelectV2.Option>
 *   <SelectV2.Option value="green">Green</SelectV2.Option>
 * </SelectV2.Group>
 * ```
 */
export function SelectV2GroupLabel(props: SelectV2GroupLabelProps) {
  return null;
}

/**
 * Typeguard function that will check if a React.Node is a SelectV2.Group
 * @internal
 */
export function _isSelectV2GroupElement(
  element: React.ReactNode,
): element is React.ReactElement<SelectV2GroupProps> {
  if (isElement(element) && element.type === SelectV2Group) {
    return true;
  }
  return false;
}

/**
 * Props for the SelectV2Group component
 */
export type SelectV2GroupProps = PropsWithChildren<unknown> &
  StylingProps &
  DataTestId;

/**
 * `SelectV2.Group` defines a group of options that share some commonalities.
 * The component is only valid within a `SelectV2.Content` element.
 *
 * @example
 * ```tsx
 * <SelectV2.Content>
 *   <SelectV2.Group>
 *     <SelectV2.GroupLabel>Colors</SelectV2.GroupLabel>
 *     <SelectV2.Option value="red">Red</SelectV2.Option>
 *     <SelectV2.Option value="green">Green</SelectV2.Option>
 *   </SelectV2.Group>
 * </SelectV2.Content>
 * ```
 */
export function SelectV2Group(props: SelectV2GroupProps) {
  return null;
}
